<?php
define('APP_INIT',true); require_once __DIR__.'/../config/app.php';
if(!empty($_SESSION['user_id']) && ($_SESSION['is_platform_admin']??false)){header('Location: '.BASE_URL.'/admin/');exit;}$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!verifyCsrfToken($_POST['csrf_token']??''))$error='Invalid security token.';else{$db=Database::getConnection();$s=$db->prepare('SELECT u.*,r.slug role_slug,r.name role_name FROM users u JOIN roles r ON r.id=u.role_id WHERE u.username=:username AND u.is_platform_admin=1 LIMIT 1');$s->execute([':username'=>trim($_POST['username']??'')]);$user=$s->fetch();if($user&&$user['status']==='active'&&password_verify($_POST['password']??'',$user['password'])){session_regenerate_id(true);$_SESSION['user_id']=(int)$user['id'];$_SESSION['user_name']=$user['name'];$_SESSION['user_username']=$user['username'];$_SESSION['user_role_id']=(int)$user['role_id'];$_SESSION['user_role_slug']=$user['role_slug'];$_SESSION['user_role_name']=$user['role_name'];$_SESSION['tenant_id']=(int)$user['tenant_id'];$_SESSION['is_platform_admin']=true;$_SESSION['last_activity']=time();require_once ROOT_PATH.'/includes/permission_check.php';$_SESSION['user_permissions']=loadUserPermissions((int)$user['role_id']);logAudit('platform_auth','login',(string)$user['id'],null,['status'=>'success']);header('Location: '.BASE_URL.'/admin/');exit;}$error='Invalid platform administrator credentials.';}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Platform Admin Login</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#081225;color:#fff}.card{background:#111f3d}</style></head><body><main class="container py-5"><div class="card mx-auto p-4" style="max-width:420px"><h3>Platform Admin</h3><p class="text-secondary">SaaS owner/operator access only.</p><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif?><form method="post"><?php echo csrfField()?><label>Username</label><input name="username" required class="form-control mb-3"><label>Password</label><input type="password" name="password" required class="form-control mb-3"><button class="btn btn-primary w-100">Sign in to Platform</button></form><a class="d-block text-center mt-3" href="<?=BASE_URL?>/login.php">Customer login</a></div></main></body></html>
